#include <stdio.h>

/* MT-2019 midterm warm-up: detect byte order without library calls */
int is_big_endian(void) {
    int x = 1;
    unsigned char *p = (unsigned char *) &x;
    return *p == 0;
}

/* Brian Kernighan's popcount: each iteration clears the lowest set bit */
int popcount(unsigned x) {
    int count = 0;
    while (x) {
        x &= x - 1;
        count++;
    }
    return count;
}

/* Count trailing zeros by isolating the lowest set bit, x & (-x) */
int count_trailing_zeros(unsigned x) {
    if (x == 0) return 32;
    unsigned lowbit = x & (~x + 1);
    int k = 0;
    while (!((lowbit >> k) & 1)) k++;
    return k;
}

int main(void) {
    printf("machine is %s-endian\n", is_big_endian() ? "big" : "little");

    int x = -20;                          /* 0xFFFFFFEC */
    unsigned ux = (unsigned) x;
    printf("x = %d (0x%08X)\n", x, ux);
    printf("x >> 2 (arithmetic) = %d\n", x >> 2);
    printf("ux >> 2 (logical)   = %u (0x%08X)\n", ux >> 2, ux >> 2);
    printf("popcount(ux) = %d\n", popcount(ux));
    printf("ctz(ux)      = %d\n", count_trailing_zeros(ux));
    return 0;
}

